  ('643f43d7-e387-5abf-9cfe-49cea263fe8b', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'medium',
   $q$Read the sentences: "The orchestra rehearsed for six weeks. It performed the symphony without a single mistake." Which choice combines them correctly with a participial phrase?$q$, $q$[{"text":"The orchestra rehearsed for six weeks, it performed the symphony without a single mistake.","is_correct":false,"misconception_token":"comma-splice"},{"text":"Having rehearsed for six weeks, the orchestra performed the symphony without a single mistake.","is_correct":true},{"text":"Having rehearsed for six weeks, the symphony was performed without a single mistake.","is_correct":false,"misconception_token":"dangling-modifier"},{"text":"The orchestra having rehearsed for six weeks and performing the symphony without a mistake.","is_correct":false,"misconception_token":"sentence-fragment"}]$q$::jsonb, $q$Having rehearsed for six weeks, the orchestra performed the symphony without a single mistake.$q$, $q$"Having rehearsed for six weeks" correctly modifies "the orchestra," which is the subject that did the rehearsing. In the first choice the phrase modifies "the symphony," which could not rehearse, so the modifier dangles.$q$, 'draft', null)
