  ('3227cac7-a480-563b-93ff-b27de4e9d87e', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'medium',
   $q$Read the sentences: "The power went out. Afterward, the class finished the experiment by flashlight." Which choice uses a dependent clause to keep this order of events?$q$, $q$[{"text":"Before the power went out, the class finished the experiment by flashlight.","is_correct":false,"misconception_token":"reverses-sequence"},{"text":"The power went out, the class finished the experiment by flashlight.","is_correct":false,"misconception_token":"comma-splice"},{"text":"Whenever the power went out, the class finished the experiment by flashlight.","is_correct":false,"misconception_token":"changes-to-habitual"},{"text":"After the power went out, the class finished the experiment by flashlight.","is_correct":true}]$q$::jsonb, $q$After the power went out, the class finished the experiment by flashlight.$q$, $q$"After the power went out" is an adverbial clause that places the outage first, matching the original order. "Before" reverses the events, and "Whenever" wrongly suggests the outage happened again and again.$q$, 'draft', null)
