  ('bf59d94d-48f0-51ed-a96c-838d28480451', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'hard',
   $q$Which sentence uses a noun clause as its subject?$q$, $q$[{"text":"Whoever finishes the puzzle first will choose the next game.","is_correct":true},{"text":"The puzzle that Rafael finished first was the hardest one.","is_correct":false,"misconception_token":"confuses-relative-noun-clause"},{"text":"When the puzzle is finished, we will choose the next game.","is_correct":false,"misconception_token":"confuses-adverbial-noun-clause"},{"text":"Finishing the puzzle first, Rafael chose the next game.","is_correct":false,"misconception_token":"phrase-called-clause"}]$q$::jsonb, $q$Whoever finishes the puzzle first will choose the next game.$q$, $q$"Whoever finishes the puzzle first" has its own subject and verb and acts as the subject of "will choose," so it is a noun clause. "When the puzzle is finished" is an adverbial clause that tells when, and the main subject of that sentence is "we."$q$, 'draft', null)
